def reference(text: str) -> str:
    out = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] != " ":
            out.append(text[i])
            i += 1
        else:
            j = i
            while j < n and text[j] == " ":
                j += 1
            run = j - i
            if run > 2:
                out.append("-")
            else:
                out.append("_" * run)
            i = j
    return "".join(out)


def test_separate_runs_each_mapped():
    assert fix_spaces("a  b   c") == "a__b-c"
    assert fix_spaces("a   b  c    d") == "a-b__c-d"
